insert into public.places (slug,name,category,description,lat,lng,photos,photo_credits,featured,active,sort) values
('cofete','Playa de Cofete','playa','{"es": "Playa salvaje de más de 12 km al pie del macizo de Jandía. Se llega por pista de tierra; el baño es peligroso por las corrientes.", "en": "A wild beach over 12 km long beneath the Jandía mountains. Reached by a dirt track; swimming is dangerous because of strong currents.", "it": "Spiaggia selvaggia di oltre 12 km ai piedi del massiccio di Jandía. Si arriva su pista sterrata; il bagno è pericoloso per le correnti.", "de": "Wilder, über 12 km langer Strand unterhalb des Jandía-Massivs. Zufahrt über eine Schotterpiste; Baden wegen starker Strömungen gefährlich."}'::jsonb,28.111667,-14.390278,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/cofete-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/cofete-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/cofete-3.jpg']::text[],'[{"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Playa_de_Cofete_-_Fuerteventura_-_02.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:View_from_Degollada_de_Cofete.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Cofete_Cemetery_-_Fuerteventura_-_02.jpg"}]'::jsonb,true,true,1),
('sotavento','Playa de Sotavento','playa','{"es": "Laguna de marea y kilómetros de arena blanca en la costa de Jandía. Paraíso del windsurf y del kitesurf.", "en": "A tidal lagoon and miles of white sand on the Jandía coast. A paradise for windsurfing and kitesurfing.", "it": "Laguna di marea e chilometri di sabbia bianca sulla costa di Jandía. Paradiso del windsurf e del kitesurf.", "de": "Gezeitenlagune und kilometerlanger weißer Sand an der Küste von Jandía. Ein Paradies für Wind- und Kitesurfer."}'::jsonb,28.100556,-14.271389,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/sotavento-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/sotavento-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/sotavento-3.jpg']::text[],'[{"author": "dirkvorderstrasse", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File:Luftbild_Playa_de_Sotavento,_Lagune_-_51512711614.jpg"}, {"author": "Frank Vincentz", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:P%C3%A1jara_-_Playa_de_Sotavento_02_ies.jpg"}, {"author": "Frank Vincentz", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:P%C3%A1jara_-_Playa_de_Sotavento_01_ies.jpg"}]'::jsonb,true,true,2),
('dunas-corralejo','Dunas de Corralejo','naturaleza','{"es": "Parque natural de dunas de arena blanca junto al mar, al sur de Corralejo. La FV-1 lo atraviesa.", "en": "A natural park of white sand dunes by the sea, south of Corralejo. The FV-1 road runs right through it.", "it": "Parco naturale di dune di sabbia bianca sul mare, a sud di Corralejo. La FV-1 lo attraversa.", "de": "Naturpark mit weißen Sanddünen am Meer, südlich von Corralejo. Die FV-1 führt mitten hindurch."}'::jsonb,28.715246,-13.839299,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/dunas-corralejo-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/dunas-corralejo-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/dunas-corralejo-3.jpg']::text[],'[{"author": "Benjamín Núñez González", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Arena,_Dunas_de_Corralejo,_Fuerteventura,_Espa%C3%B1a,_2015.JPG"}, {"author": "Benjamín Núñez González", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Monta%C3%B1a_y_duna,_Dunas_de_Corralejo,_Fuerteventura,_Espa%C3%B1a,_2015.JPG"}, {"author": "Benjamín Núñez González", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Matas,_Dunas_de_Corralejo,_Fuerteventura,_Espa%C3%B1a,_2015.JPG"}]'::jsonb,true,true,3),
('isla-de-lobos','Isla de Lobos','naturaleza','{"es": "Islote protegido frente a Corralejo, con ferry diario desde el puerto. Sendero alrededor del volcán, faro y la laguna de La Concha. Para visitarlo hace falta una autorización gratuita.", "en": "A protected islet off Corralejo with a daily ferry from the harbour. Trail around the volcano, a lighthouse and La Concha lagoon. A free permit is required to visit.", "it": "Isolotto protetto davanti a Corralejo, con traghetto giornaliero dal porto. Sentiero intorno al vulcano, faro e la laguna de La Concha. Per visitarlo serve un’autorizzazione gratuita.", "de": "Geschütztes Inselchen vor Corralejo mit täglicher Fähre ab dem Hafen. Rundweg um den Vulkan, Leuchtturm und die Lagune La Concha. Für den Besuch ist eine kostenlose Genehmigung nötig."}'::jsonb,28.75223,-13.81842,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/isla-de-lobos-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/isla-de-lobos-2.jpg']::text[],'[{"author": "Mike Peel", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:At_Fuerteventura_2022_105.jpg"}, {"author": "Mike Peel", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:At_Fuerteventura_2022_114.jpg"}]'::jsonb,true,true,4),
('el-cotillo','El Cotillo','playa','{"es": "Pueblo pesquero del noroeste con calas de agua turquesa, playas para surf y algunas de las mejores puestas de sol de la isla.", "en": "A fishing village in the north-west with turquoise coves, surf beaches and some of the best sunsets on the island.", "it": "Paese di pescatori a nord-ovest con calette turchesi, spiagge da surf e alcuni dei tramonti più belli dell’isola.", "de": "Fischerdorf im Nordwesten mit türkisfarbenen Buchten, Surfstränden und einigen der schönsten Sonnenuntergänge der Insel."}'::jsonb,28.683611,-14.011111,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/el-cotillo-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/el-cotillo-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/el-cotillo-3.jpg']::text[],'[{"author": "Dariusz Jemielniak (\"Pundit\")", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Playa_del_Castillo_(El_Cotillo,_Fuerteventura)_08.jpg"}, {"author": "Dariusz Jemielniak (\"Pundit\")", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Playa_del_Castillo_(El_Cotillo,_Fuerteventura)_17.jpg"}, {"author": "Dariusz Jemielniak (\"Pundit\")", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Playa_del_Castillo_(El_Cotillo,_Fuerteventura)_15.jpg"}]'::jsonb,true,true,5),
('ajuy','Ajuy y sus cuevas','naturaleza','{"es": "Pueblo de pescadores con playa de arena negra y grandes cuevas marinas en rocas que están entre las más antiguas de Canarias. Monumento natural.", "en": "A fishing village with a black-sand beach and huge sea caves in some of the oldest rocks of the Canary Islands. A natural monument.", "it": "Paese di pescatori con spiaggia di sabbia nera e grandi grotte marine in rocce tra le più antiche delle Canarie. Monumento naturale.", "de": "Fischerdorf mit schwarzem Sandstrand und großen Meereshöhlen in einigen der ältesten Gesteine der Kanaren. Naturdenkmal."}'::jsonb,28.40325,-14.15597,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/ajuy-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/ajuy-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/ajuy-3.jpg']::text[],'[{"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Caleta_Negra_-_Ajuy_-_01.jpg"}, {"author": "Frank Vincentz", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:P%C3%A1jara_-_Ajuy_-_Monumento_Natural_-_Hornos_04_ies.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Breakers_-_Fuerteventura.JPG"}]'::jsonb,true,true,6),
('garcey','Playa del Garcey','playa','{"es": "Playa remota de la costa oeste con arcos de roca, famosa por el naufragio del American Star (hoy casi desaparecido). Mar bravo: no apta para el baño.", "en": "A remote west-coast beach with rock arches, famous for the American Star shipwreck (now almost gone). Rough sea: not for swimming.", "it": "Spiaggia remota della costa ovest con archi di roccia, famosa per il naufragio dell’American Star (oggi quasi scomparso). Mare agitato: non adatta al bagno.", "de": "Abgelegener Strand an der Westküste mit Felsbögen, bekannt für das Wrack der American Star (heute fast verschwunden). Raue See: nicht zum Baden."}'::jsonb,28.346856,-14.177045,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/garcey-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/garcey-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/garcey-3.jpg']::text[],'[{"author": "Tony Hisgett from Birmingham, UK", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File:Playa_de_Garcey_(3314115501).jpg"}, {"author": "Jarek Prokop", "license": "CC BY 3.0", "license_url": "https://creativecommons.org/licenses/by/3.0", "source": "https://commons.wikimedia.org/wiki/File:Playa_de_Garcey_-_panoramio.jpg"}, {"author": "Wollex", "license": "CC BY-SA 3.0", "license_url": "http://creativecommons.org/licenses/by-sa/3.0/", "source": "https://commons.wikimedia.org/wiki/File:Shipwreck_of_the_SS_American_Star_on_the_shore_of_Fuerteventura.jpg"}]'::jsonb,false,true,7),
('morro-velosa','Mirador Morro Velosa','mirador','{"es": "Mirador en lo alto del macizo de Betancuria, junto a la FV-30, con vistas a gran parte del norte de la isla.", "en": "A viewpoint high on the Betancuria massif, beside the FV-30, overlooking much of the north of the island.", "it": "Belvedere in cima al massiccio di Betancuria, lungo la FV-30, con vista su gran parte del nord dell’isola.", "de": "Aussichtspunkt hoch oben im Betancuria-Massiv an der FV-30 mit Blick über einen großen Teil des Inselnordens."}'::jsonb,28.438616,-14.050006,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/morro-velosa-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/morro-velosa-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/morro-velosa-3.jpg']::text[],'[{"author": "Gerd Eichmann", "license": "CC BY 4.0", "license_url": "https://creativecommons.org/licenses/by/4.0", "source": "https://commons.wikimedia.org/wiki/File:Fuerteventura-Mirador_Morro_Velosa-14-2015-gje.jpg"}, {"author": "Cayambe", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Fuerteventura_-_Mirador_de_Guise_y_Ayose_-_Statues.jpg"}, {"author": "Frank Vincentz", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Betancuria_-_FV-30_-_Morro_Velosa_(Mirador_Corrales_de_Guize)_02_ies.jpg"}]'::jsonb,false,true,8),
('calderon-hondo','Calderón Hondo','naturaleza','{"es": "Volcán con un cráter profundo cerca de Lajares. Sendero fácil hasta el borde, con vistas al norte de la isla.", "en": "A volcano with a deep crater near Lajares. An easy trail leads to the rim, with views over the north of the island.", "it": "Vulcano con un cratere profondo vicino a Lajares. Un sentiero facile porta fino al bordo, con vista sul nord dell’isola.", "de": "Vulkan mit tiefem Krater bei Lajares. Ein leichter Wanderweg führt bis zum Kraterrand, mit Blick über den Inselnorden."}'::jsonb,28.698576,-13.920864,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/calderon-hondo-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/calderon-hondo-2.jpg']::text[],'[{"author": "Matzetatz", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Calderon_Hondo.jpg"}, {"author": "Jensibua", "license": "CC0", "license_url": "http://creativecommons.org/publicdomain/zero/1.0/deed.en", "source": "https://commons.wikimedia.org/wiki/File:Calderon_Hondo_Pano.jpg"}]'::jsonb,false,true,9),
('entallada','Faro de la Entallada','mirador','{"es": "Faro sobre un acantilado de la costa este, uno de los puntos de Canarias más cercanos a África. Vistas espectaculares al océano.", "en": "A lighthouse on an east-coast cliff, one of the points of the Canaries closest to Africa. Spectacular ocean views.", "it": "Faro su una scogliera della costa est, uno dei punti delle Canarie più vicini all’Africa. Vista spettacolare sull’oceano.", "de": "Leuchtturm auf einer Klippe an der Ostküste, einer der afrikanähesten Punkte der Kanaren. Spektakulärer Blick aufs Meer."}'::jsonb,28.230278,-13.948611,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/entallada-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/entallada-2.jpg']::text[],'[{"author": "Alistair Young", "license": "CC BY 2.0", "license_url": "https://creativecommons.org/licenses/by/2.0", "source": "https://commons.wikimedia.org/wiki/File:Entallada_Lighthouse.jpg"}, {"author": "JensKunstfreund", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Beim_Leuchtturm_(Faro_de_la_Entallada)_10.jpg"}]'::jsonb,false,true,10),
('betancuria','Betancuria','pueblo','{"es": "Primera capital de Canarias, fundada en 1404 en un valle entre montañas. Casco histórico e iglesia de Santa María.", "en": "The first capital of the Canary Islands, founded in 1404 in a mountain valley. Historic centre and the church of Santa María.", "it": "Prima capitale delle Canarie, fondata nel 1404 in una valle tra le montagne. Centro storico e chiesa di Santa María.", "de": "Erste Hauptstadt der Kanaren, 1404 in einem Bergtal gegründet. Historischer Ortskern und Kirche Santa María."}'::jsonb,28.424722,-14.057219,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/betancuria-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/betancuria-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/betancuria-3.jpg']::text[],'[{"author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Betancuria_(Fuerteventura,_Spain),_Iglesia_de_Santa_Mar%C3%ADa_--_2025_--_7185.jpg"}, {"author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Betancuria_(Fuerteventura,_Spain),_Iglesia_de_Santa_Mar%C3%ADa_--_2025_--_7199.jpg"}, {"author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Betancuria_(Fuerteventura,_Spain),_Kaktus_--_2025_--_7205.jpg"}]'::jsonb,false,true,11),
('morro-jable','Playa del Matorral (Morro Jable)','playa','{"es": "Larga playa de arena dorada junto al paseo de Morro Jable, con faro y un saladar protegido detrás de la arena.", "en": "A long golden beach along the Morro Jable promenade, with a lighthouse and a protected salt marsh behind the sand.", "it": "Lunga spiaggia dorata lungo il lungomare di Morro Jable, con faro e una zona umida salmastra protetta dietro la sabbia.", "de": "Langer goldener Strand an der Promenade von Morro Jable, mit Leuchtturm und geschütztem Salzwiesengebiet hinter dem Sand."}'::jsonb,28.044611,-14.335189,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/morro-jable-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/morro-jable-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/morro-jable-3.jpg']::text[],'[{"author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Morro_Jable_(Fuerteventura,_Spain),_Strand,_Rettungsturm_--_2025_--_2498.jpg"}, {"author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Morro_Jable_(Fuerteventura,_Spain),_Strand,_Rettungsturm_--_2025_--_2447.jpg"}, {"author": "Dietmar Rabich", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0", "source": "https://commons.wikimedia.org/wiki/File:Morro_Jable_(Fuerteventura,_Spain),_Strand,_Brandung_--_2025_--_2465.jpg"}]'::jsonb,false,true,12),
('las-penitas','Barranco de las Peñitas','naturaleza','{"es": "Barranco de roca con una antigua presa y la ermita de la Peña, cerca de Vega de Río Palmas. Paseo corto y muy fotogénico.", "en": "A rocky gorge with an old dam and the hermitage of La Peña, near Vega de Río Palmas. A short and very photogenic walk.", "it": "Gola rocciosa con una vecchia diga e l’eremo de la Peña, vicino a Vega de Río Palmas. Passeggiata breve e molto fotogenica.", "de": "Felsschlucht mit altem Stausee und der Einsiedelei de la Peña bei Vega de Río Palmas. Kurzer, sehr fotogener Spaziergang."}'::jsonb,28.38907,-14.09765,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/las-penitas-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/las-penitas-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/las-penitas-3.jpg']::text[],'[{"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Barranco_de_las_Pe%C3%B1itas_-_Fuerteventura_01.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Barranco_de_las_Pe%C3%B1itas_-_Fuerteventura_02.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Vega_de_R%C3%ADo_Palmas_-_Fuerteventura.jpg"}]'::jsonb,false,true,13),
('punta-jandia','Faro de Punta Jandía','mirador','{"es": "Faro en el extremo suroeste de la isla, al final de una larga pista de tierra. Paisaje desértico y océano abierto.", "en": "A lighthouse at the south-western tip of the island, at the end of a long dirt track. Desert landscape and open ocean.", "it": "Faro all’estremità sud-ovest dell’isola, alla fine di una lunga pista sterrata. Paesaggio desertico e oceano aperto.", "de": "Leuchtturm an der Südwestspitze der Insel am Ende einer langen Schotterpiste. Wüstenlandschaft und offener Ozean."}'::jsonb,28.0657,-14.5071,ARRAY['https://stocked-app.github.io/MAXORA/assets/places/punta-jandia-1.jpg','https://stocked-app.github.io/MAXORA/assets/places/punta-jandia-2.jpg','https://stocked-app.github.io/MAXORA/assets/places/punta-jandia-3.jpg']::text[],'[{"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Faro_de_Punta_Jand%C3%ADa_-_01.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Faro_de_Punta_Jand%C3%ADa_-_02.jpg"}, {"author": "H. Zell", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0", "source": "https://commons.wikimedia.org/wiki/File:Punta_de_Jand%C3%ADa_01.jpg"}]'::jsonb,false,true,14)
